def fetch_f1_calendar(year, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0434000" if __import__("os").path.isdir("./environment_mix/0434000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    endpoint = "fetch_f1_calendar"
    t0 = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_year_relaxed(y):
        if y is None:
            return None, _err("VALIDATION_ERROR", "Parameter 'year' is required.")
        if isinstance(y, bool):
            return None, _err("VALIDATION_ERROR", "Parameter 'year' must be parseable to an integer.")
        if isinstance(y, int):
            yi = y
        elif isinstance(y, str):
            if not y.strip():
                return None, _err("VALIDATION_ERROR", "Parameter 'year' must be a non-empty string.")
            try:
                yi = int(y.strip())
            except ValueError:
                return None, _err("VALIDATION_ERROR", "Parameter 'year' must be parseable to an integer.")
        else:
            return None, _err("VALIDATION_ERROR", "Parameter 'year' must be parseable to an integer.")
        if yi < 1950 or yi > 2100:
            return None, _err("VALIDATION_ERROR", "Parameter 'year' must be between 1950 and 2100 (inclusive).")
        return yi, None

    def _log_and_return(resp, status, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        # Find an existing log collection, otherwise default to request_logs.json
        fname = None
        for cand in ("request_logs.json", "requests.json", "audit_logs.json", "usage.json"):
            if os.path.exists(os.path.join(_DB, cand)):
                fname = cand
                break
        if fname is None:
            fname = "request_logs.json"
        logs = _load(fname)
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "timestamp": _now_iso(),
        })
        _save(fname, logs)
        return resp

    def _enforce_limits():
        # If no log file exists, create request_logs.json and enforce based on it
        fname = None
        for cand in ("request_logs.json", "requests.json", "audit_logs.json", "usage.json"):
            if os.path.exists(os.path.join(_DB, cand)):
                fname = cand
                break
        if fname is None:
            fname = "request_logs.json"
        logs = _load(fname)
        if not isinstance(logs, list):
            return None

        now = datetime.datetime.utcnow()
        window_start = now - datetime.timedelta(seconds=60)
        day_start = now - datetime.timedelta(days=1)

        def _parse_ts(s):
            if not isinstance(s, str):
                return None
            try:
                return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                return None

        recent = 0
        daily = 0
        for r in logs[-5000:]:
            dt = _parse_ts(r.get("timestamp"))
            if dt is None:
                continue
            if dt >= window_start:
                recent += 1
            if dt >= day_start:
                daily += 1

        if recent >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        if daily >= 5000:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        return None

    lim_err = _enforce_limits()
    if lim_err:
        return _log_and_return(lim_err, "error", lim_err["error"]["code"])

    yi, e = _parse_year_relaxed(year)
    if e:
        return _log_and_return(e, "error", e["error"]["code"])

    seasons = _load("seasons.json")
    if not isinstance(seasons, list):
        seasons = []
    season = None
    for s in seasons:
        if isinstance(s, dict) and s.get("year") == yi:
            season = s
            break
    if not season:
        return _log_and_return(_err("NOT_FOUND", "Season not found."), "error", "NOT_FOUND")

    # Failed season serving rule: do not serve failed unless there is a stale active snapshot.
    # We implement this as: if season is failed, look for another season row for same year in active/archived
    # (stale snapshot). If not present, refuse.
    if season.get("status") == "failed":
        stale = None
        for s in seasons:
            if isinstance(s, dict) and s.get("year") == yi and s.get("status") in ("active", "archived"):
                stale = s
                break
        if not stale:
            return _log_and_return(_err("CONFLICT", "Season is in 'failed' state and no stale active snapshot is available."), "error", "CONFLICT")
        season = stale

    season_id = season.get("id")
    events = _load("events.json")
    if not isinstance(events, list):
        events = []
    out_events = [ev for ev in events if isinstance(ev, dict) and ev.get("season_id") == season_id]
    out_events.sort(key=lambda r: (r.get("round") if isinstance(r.get("round"), int) else 10**9, str(r.get("id") or "")))

    resp = {
        "season": season,
        "events": out_events,
        "count": len(out_events),
    }
    return _log_and_return(resp, "success", None)

