    # During refreshing, reads should prefer non-provisional when available.
    rows = [r for r in rc if isinstance(r, dict) and r.get("season_id") == season_id and r.get("kind") == "constructor_standing"]
    if not rows:
        return _log_and_return(_err("NOT_FOUND", "Constructor standings not available for this season."), "error", "NOT_FOUND")

    has_latest_null = any(r.get("standing_round") is None for r in rows)
    if has_latest_null:
        chosen = [r for r in rows if r.get("standing_round") is None]
    else:
        rounds = [r.get("standing_round") for r in rows if isinstance(r.get("standing_round"), int)]
        max_round = max(rounds) if rounds else None
        if max_round is None:
            return _log_and_return(_err("NOT_FOUND", "Constructor standings not available for this season."), "error", "NOT_FOUND")
        chosen = [r for r in rows if r.get("standing_round") == max_round]

    # If season refreshing, prefer non-provisional if any.
    if season.get("status") == "refreshing":
        nonprov = [r for r in chosen if r.get("data_status") in ("official", "amended")]
        if nonprov:
            chosen = nonprov

    def _pos_key(r):
        p = r.get("position")
        if isinstance(p, int) and p >= 1:
            return (0, p)
        return (1, 10**9)

    chosen.sort(key=_pos_key)

    enriched = []
    for r in chosen:
        cid = r.get("constructor_id")
        rr = dict(r)
        rr["constructor"] = con_by_id.get(cid)
        enriched.append(rr)

    resp = {
        "season": season,
        "standing_round": None if has_latest_null else (chosen[0].get("standing_round") if chosen else None),
        "rows": enriched,
        "count": len(enriched),
    }
    return _log_and_return(resp, "success", None)

