    constructors = _load("constructors.json")
    if not isinstance(constructors, list):
        constructors = []
    rc = _load("race_classifications.json")
    if not isinstance(rc, list):
        rc = []

    ev_by_id = {ev.get("id"): ev for ev in events if isinstance(ev, dict) and isinstance(ev.get("id"), str)}
    drv_by_id = {d.get("id"): d for d in drivers if isinstance(d, dict) and isinstance(d.get("id"), str)}
    con_by_id = {c.get("id"): c for c in constructors if isinstance(c, dict) and isinstance(c.get("id"), str)}

    # Find race result rows for the season, joined to event/drv/con
    rows = [r for r in rc if isinstance(r, dict) and r.get("season_id") == season_id and r.get("kind") == "race_result"]
    if not rows:
        return _log_and_return(_err("NOT_FOUND", "Race results not available for this season."), "error", "NOT_FOUND")

    # Refreshing rule: prefer non-provisional rows when available per event.
    # We'll group, then if any non-provisional exists for an event, serve only those.
    by_event = {}
    for r in rows:
        eid = r.get("event_id")
        if not isinstance(eid, str):
            continue
        by_event.setdefault(eid, []).append(r)

    # Build output grouped by event round
    grouped = []
    for eid, rlist in by_event.items():
        ev = ev_by_id.get(eid)
        # Skip if event doesn't exist (stale FK) but keep deterministic behavior: ignore unknown events
        if not isinstance(ev, dict):
            continue

        chosen = rlist
        if season.get("status") == "refreshing":
            nonprov = [x for x in rlist if x.get("data_status") in ("official", "amended")]
            if nonprov:
                chosen = nonprov

        def _pos_key(r):
            p = r.get("position")
            if isinstance(p, int) and p >= 1:
                return (0, p)
            return (1, 10**9)

        chosen_sorted = sorted(chosen, key=_pos_key)
        enriched_rows = []
        for r in chosen_sorted:
            rr = dict(r)
            rr["driver"] = drv_by_id.get(r.get("driver_id"))
            rr["constructor"] = con_by_id.get(r.get("constructor_id"))
            rr["event"] = ev
            enriched_rows.append(rr)

        grouped.append({
            "event_id": eid,
            "round": ev.get("round"),
            "race_name": ev.get("race_name"),
            "event": ev,
            "results": enriched_rows
        })

    grouped.sort(key=lambda g: (g.get("round") if isinstance(g.get("round"), int) else 10**9, str(g.get("event_id") or "")))

    resp = {
        "season": season,
        "events": grouped,
        "count_events": len(grouped),
        "count_results": sum(len(g.get("results") or []) for g in grouped),
    }
    return _log_and_return(resp, "success", None)

def fetch_f1_seasons(year=None, status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0434000" if __import__("os").path.isdir("./environment_mix/0434000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    endpoint = "fetch_f1_seasons"
    t0 = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_year_optional_relaxed(y):
        if y is None:
            return None, None
        if isinstance(y, bool):
            return None, _err("VALIDATION_ERROR", "year must be parseable to an integer in [1950, 2100].")
        if isinstance(y, int):
            yi = y
        elif isinstance(y, str):
            if not y.strip():
                return None, _err("VALIDATION_ERROR", "year must be a non-empty string when provided.")
            try:
                yi = int(y.strip())
            except ValueError:
                return None, _err("VALIDATION_ERROR", "year must be parseable to an integer in [1950, 2100].")
        else:
            return None, _err("VALIDATION_ERROR", "year must be parseable to an integer in [1950, 2100].")
        if yi < 1950 or yi > 2100:
            return None, _err("VALIDATION_ERROR", "year must be between 1950 and 2100 (inclusive).")
        return yi, None

    def _parse_cursor(c):
        if c is None:
            return 0, None
        if not isinstance(c, str) or not c:
            return None, _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided")
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8")).decode("utf-8")
            if not raw.startswith("offset:"):
                return None, _err("VALIDATION_ERROR", "cursor is invalid")
            off = int(raw.split(":", 1)[1])
            if off < 0:
                return None, _err("VALIDATION_ERROR", "cursor is invalid")
            return off, None
        except Exception:
            return None, _err("VALIDATION_ERROR", "cursor is invalid")

    def _mk_cursor(off):
        return base64.urlsafe_b64encode(f"offset:{off}".encode("utf-8")).decode("utf-8")

    def _log_and_return(resp, status_str, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        fname = None
        for cand in ("request_logs.json", "requests.json", "audit_logs.json", "usage.json"):
            if os.path.exists(os.path.join(_DB, cand)):
                fname = cand
                break
        if fname is None:
            fname = "request_logs.json"
        logs = _load(fname)
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
            "endpoint": endpoint,
            "status": status_str,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "timestamp": _now_iso(),
        })
        _save(fname, logs)
        return resp

    def _enforce_limits():
        fname = None
        for cand in ("request_logs.json", "requests.json", "audit_logs.json", "usage.json"):
            if os.path.exists(os.path.join(_DB, cand)):
                fname = cand
                break
        if fname is None:
            fname = "request_logs.json"
        logs = _load(fname)
        if not isinstance(logs, list):
            return None

        now = datetime.datetime.utcnow()
        window_start = now - datetime.timedelta(seconds=60)
        day_start = now - datetime.timedelta(days=1)

        def _parse_ts(s):
            if not isinstance(s, str):
                return None
            try:
                return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                return None

        recent = 0
        daily = 0
        for r in logs[-5000:]:
            dt = _parse_ts(r.get("timestamp"))
            if dt is None:
                continue
            if dt >= window_start:
                recent += 1
            if dt >= day_start:
                daily += 1

        if recent >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        if daily >= 5000:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        return None

    lim_err = _enforce_limits()
    if lim_err:
        return _log_and_return(lim_err, "error", lim_err["error"]["code"])

    if status is not None:
        if not isinstance(status, str) or status not in ("pending", "active", "refreshing", "archived", "failed"):
            e = _err("VALIDATION_ERROR", "Invalid status filter.")
            return _log_and_return(e, "error", "VALIDATION_ERROR")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or isinstance(limit, bool) or limit < 1 or limit > 200:
        e = _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
        return _log_and_return(e, "error", "VALIDATION_ERROR")

    yi, e = _parse_year_optional_relaxed(year)
    if e:
        return _log_and_return(e, "error", e["error"]["code"])

    off, ce = _parse_cursor(cursor)
    if ce:
        return _log_and_return(ce, "error", ce["error"]["code"])

    seasons = _load("seasons.json")
    if not isinstance(seasons, list):
        seasons = []

    rows = [s for s in seasons if isinstance(s, dict)]
    if yi is not None:
        rows = [s for s in rows if s.get("year") == yi]
    if status is not None:
        rows = [s for s in rows if s.get("status") == status]

    rows.sort(key=lambda r: (r.get("year") if isinstance(r.get("year"), int) else -1), reverse=True)

    total = len(rows)
    page = rows[off:off + limit]
    next_off = off + len(page)
    has_more = next_off < total
    next_cursor = _mk_cursor(next_off) if has_more else None

    resp = {
        "rows": page,
        "total": total,
        "limit": limit,
        "cursor": cursor,
        "has_more": has_more,
        "next_cursor": next_cursor
    }
    return _log_and_return(resp, "success", None)

