        if not isinstance(source, str) or not source:
            return _log_and_return(_err("VALIDATION_ERROR", "source must be a non-empty string when provided."), "error", "VALIDATION_ERROR")
        if source not in ("ergast", "fastf1", "official_api", "other"):
            return _log_and_return(_err("VALIDATION_ERROR", "source must be one of: ergast, fastf1, official_api, other."), "error", "VALIDATION_ERROR")

    if source_revision is not None and (not isinstance(source_revision, str) or not source_revision):
        return _log_and_return(_err("VALIDATION_ERROR", "source_revision must be a non-empty string when provided."), "error", "VALIDATION_ERROR")

    if status is not None:
        if not isinstance(status, str) or status not in ("pending", "active", "refreshing", "archived", "failed"):
            return _log_and_return(_err("VALIDATION_ERROR", "Invalid status."), "error", "VALIDATION_ERROR")

    last_synced_norm, dt_err = _parse_dt_optional(last_synced_at, "last_synced_at")
    if dt_err:
        return _log_and_return(dt_err, "error", dt_err["error"]["code"])

    seasons = _load("seasons.json")
    if not isinstance(seasons, list):
        seasons = []

    row = None
    idx = None
    for i, s in enumerate(seasons):
        if isinstance(s, dict) and s.get("year") == yi:
            row = s
            idx = i
            break

    now_iso = _now_iso()
    transitions = {
        "pending": ("active", "failed"),
        "active": ("refreshing", "archived"),
        "refreshing": ("active", "failed"),
        "failed": ("refreshing", "archived"),
        "archived": (),
    }

    if row is None:
        # Create
        new_status = status or "pending"
        if new_status not in transitions:
            return _log_and_return(_err("VALIDATION_ERROR", "Invalid season status."), "error", "VALIDATION_ERROR")
        new_row = {
            "id": f"f1_season_{yi}",
            "year": yi,
            "status": new_status,
            "source": source or "other",
            "source_revision": source_revision,
            "last_synced_at": last_synced_norm,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        # unique(year) - ensured by search above
        seasons.append(new_row)
        _save("seasons.json", seasons)
        return _log_and_return({"season": new_row}, "success", None)

    # Update existing
    updated = dict(row)
    if source is not None:
        updated["source"] = source
    if source_revision is not None:
        updated["source_revision"] = source_revision
    if last_synced_at is not None:
        updated["last_synced_at"] = last_synced_norm

    if status is not None and status != row.get("status"):
        cur = row.get("status")
        if cur not in transitions:
            return _log_and_return(_err("CONFLICT", "Season has unknown lifecycle state."), "error", "CONFLICT")
        if status not in transitions[cur]:
            return _log_and_return(_err("INVALID_TRANSITION", f"Invalid season status transition: {cur} -> {status}."), "error", "INVALID_TRANSITION")
        updated["status"] = status

    updated["updated_at"] = now_iso
    seasons[idx] = updated
    _save("seasons.json", seasons)
    return _log_and_return({"season": updated}, "success", None)

