            dt_utc = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None, microsecond=0)
            return dt_utc.isoformat() + "Z", None
        except Exception:
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO-8601 date-time")

    def _log_and_return(resp, status_str, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        fname = None
        for cand in ("request_logs.json", "requests.json", "audit_logs.json", "usage.json"):
            if os.path.exists(os.path.join(_DB, cand)):
                fname = cand
                break
        if fname is None:
            fname = "request_logs.json"
        logs = _load(fname)
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
            "endpoint": endpoint,
            "status": status_str,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "timestamp": _now_iso(),
        })
        _save(fname, logs)
        return resp

    def _enforce_limits():
        fname = None
        for cand in ("request_logs.json", "requests.json", "audit_logs.json", "usage.json"):
            if os.path.exists(os.path.join(_DB, cand)):
                fname = cand
                break
        if fname is None:
            fname = "request_logs.json"
        logs = _load(fname)
        if not isinstance(logs, list):
            return None
        now = datetime.datetime.utcnow()
        window_start = now - datetime.timedelta(seconds=60)
        day_start = now - datetime.timedelta(days=1)

        def _parse_ts(s):
            if not isinstance(s, str):
                return None
            try:
                return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                return None

        recent = 0
        daily = 0
        for r in logs[-5000:]:
            dt = _parse_ts(r.get("timestamp"))
            if dt is None:
                continue
            if dt >= window_start:
                recent += 1
            if dt >= day_start:
                daily += 1
        if recent >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        if daily >= 5000:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        return None

    lim_err = _enforce_limits()
    if lim_err:
        return _log_and_return(lim_err, "error", lim_err["error"]["code"])

    yi, e = _parse_year_relaxed(year)
    if e:
        return _log_and_return(e, "error", e["error"]["code"])

    if not isinstance(events, list):
        return _log_and_return(_err("VALIDATION_ERROR", "events must be an array."), "error", "VALIDATION_ERROR")

    seasons = _load("seasons.json")
    if not isinstance(seasons, list):
        seasons = []
    season = None
    for s in seasons:
        if isinstance(s, dict) and s.get("year") == yi:
            season = s
            break
    if not season:
        return _log_and_return(_err("NOT_FOUND", "Season not found."), "error", "NOT_FOUND")
    if season.get("status") == "archived":
        return _log_and_return(_err("CONFLICT", "Cannot write calendar for an archived season."), "error", "CONFLICT")

    season_id = season.get("id")
    store_events = _load("events.json")
    if not isinstance(store_events, list):
        store_events = []

    now_iso = _now_iso()
    inserted = 0
    updated = 0

    # Validate payload first (atomic-ish): build normalized list
    normalized = []
    seen_rounds = set()
    for i, ev in enumerate(events):
        if not isinstance(ev, dict):
            return _log_and_return(_err("VALIDATION_ERROR", f"events[{i}] must be an object."), "error", "VALIDATION_ERROR")
        # Required fields
        for f in ("round", "race_name", "circuit_name", "circuit_country", "timezone", "race_start_at", "status"):
            if f not in ev:
                return _log_and_return(_err("VALIDATION_ERROR", f"events[{i}].{f} is required."), "error", "VALIDATION_ERROR")
        rnd = ev.get("round")
        if not isinstance(rnd, int) or isinstance(rnd, bool) or rnd < 1:
            return _log_and_return(_err("VALIDATION_ERROR", f"events[{i}].round must be an integer >= 1."), "error", "VALIDATION_ERROR")
        if rnd in seen_rounds:
            return _log_and_return(_err("CONFLICT", f"Duplicate round {rnd} in request."), "error", "CONFLICT")
        seen_rounds.add(rnd)

        st = ev.get("status")
        if not isinstance(st, str) or st not in ("scheduled", "completed", "cancelled"):
            return _log_and_return(_err("VALIDATION_ERROR", f"events[{i}].status must be one of scheduled, completed, cancelled."), "error", "VALIDATION_ERROR")

        lat = ev.get("circuit_lat")
        if lat is not None:
            if not isinstance(lat, (int, float)) or isinstance(lat, bool) or lat < -90 or lat > 90:
                return _log_and_return(_err("VALIDATION_ERROR", f"events[{i}].circuit_lat must be between -90 and 90."), "error", "VALIDATION_ERROR")
        lng = ev.get("circuit_lng")
        if lng is not None:
            if not isinstance(lng, (int, float)) or isinstance(lng, bool) or lng < -180 or lng > 180:
                return _log_and_return(_err("VALIDATION_ERROR", f"events[{i}].circuit_lng must be between -180 and 180."), "error", "VALIDATION_ERROR")

        race_start_at, de = _parse_dt_required(ev.get("race_start_at"), f"events[{i}].race_start_at")
        if de:
            return _log_and_return(de, "error", de["error"]["code"])

        def _opt_dt(field):
            return _parse_dt_optional(ev.get(field), f"events[{i}].{field}")

        qualifying_at, de = _opt_dt("qualifying_at")
        if de: return _log_and_return(de, "error", de["error"]["code"])
        sprint_at, de = _opt_dt("sprint_at")
        if de: return _log_and_return(de, "error", de["error"]["code"])
        fp1_at, de = _opt_dt("fp1_at")
        if de: return _log_and_return(de, "error", de["error"]["code"])
        fp2_at, de = _opt_dt("fp2_at")
        if de: return _log_and_return(de, "error", de["error"]["code"])
        fp3_at, de = _opt_dt("fp3_at")
        if de: return _log_and_return(de, "error", de["error"]["code"])

        normalized.append({
            "round": rnd,
            "race_name": ev.get("race_name"),
            "circuit_name": ev.get("circuit_name"),
            "circuit_city": ev.get("circuit_city"),
            "circuit_country": ev.get("circuit_country"),
            "circuit_lat": lat,
            "circuit_lng": lng,
            "timezone": ev.get("timezone"),
            "race_start_at": race_start_at,
            "qualifying_at": qualifying_at,
            "sprint_at": sprint_at,
            "fp1_at": fp1_at,
            "fp2_at": fp2_at,
            "fp3_at": fp3_at,
            "status": st,
        })

    # Apply upserts matched by (season_id, round)
    for ev in normalized:
        rnd = ev["round"]
        existing_idx = None
        existing_row = None
        for j, row in enumerate(store_events):
            if isinstance(row, dict) and row.get("season_id") == season_id and row.get("round") == rnd:
                existing_idx = j
                existing_row = row
                break

        if existing_row is None:
            new_id = f"f1_evt_{yi}_{rnd}"
            new_row = {
                "id": new_id,
                "season_id": season_id,
                "round": rnd,
                "race_name": ev["race_name"],
                "circuit_name": ev["circuit_name"],
                "circuit_city": ev["circuit_city"],
                "circuit_country": ev["circuit_country"],
                "circuit_lat": ev["circuit_lat"],
                "circuit_lng": ev["circuit_lng"],
                "timezone": ev["timezone"],
                "race_start_at": ev["race_start_at"],
                "qualifying_at": ev["qualifying_at"],
                "sprint_at": ev["sprint_at"],
                "fp1_at": ev["fp1_at"],
                "fp2_at": ev["fp2_at"],
                "fp3_at": ev["fp3_at"],
                "status": ev["status"],
                "created_at": now_iso,
                "updated_at": now_iso,
            }
            store_events.append(new_row)
            inserted += 1
        else:
            updated_row = dict(existing_row)
            for k in ("race_name", "circuit_name", "circuit_city", "circuit_country", "circuit_lat", "circuit_lng",
                      "timezone", "race_start_at", "qualifying_at", "sprint_at", "fp1_at", "fp2_at", "fp3_at", "status"):
                updated_row[k] = ev[k]
            updated_row["updated_at"] = now_iso
            store_events[existing_idx] = updated_row
            updated += 1

    if inserted == 0 and updated == 0:
        return _log_and_return(_err("NOT_FOUND", "No events matched for upsert."), "error", "NOT_FOUND")

    _save("events.json", store_events)
    return _log_and_return({"season_id": season_id, "inserted": inserted, "updated": updated, "total_written": inserted + updated}, "success", None)

def upsert_f1_results_and_standings(year, classifications, set_event_status=None, **_extra):
    import json, os, datetime, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0434000" if __import__("os").path.isdir("./environment_mix/0434000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    endpoint = "upsert_f1_results_and_standings"
    t0 = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_year(y):
        if y is None:
            return None, _err("VALIDATION_ERROR", "Parameter 'year' is required.")
        if isinstance(y, bool):
            return None, _err("VALIDATION_ERROR", "Parameter 'year' must be parseable to an integer.")
        if isinstance(y, int):
            yi = y
        elif isinstance(y, str):
            if not y.strip():
                return None, _err("VALIDATION_ERROR", "Parameter 'year' must be a non-empty string.")
            try:
                yi = int(y.strip())
            except ValueError:
                return None, _err("VALIDATION_ERROR", "Parameter 'year' must be parseable to an integer.")
        else:
            return None, _err("VALIDATION_ERROR", "Parameter 'year' must be parseable to an integer.")
        if yi < 1950 or yi > 2100:
            return None, _err("VALIDATION_ERROR", "Parameter 'year' must be between 1950 and 2100 (inclusive).")
        return yi, None

    def _pick_log_file():
        for cand in ("request_logs.json", "requests.json", "audit_logs.json", "usage.json"):
            if os.path.exists(os.path.join(_DB, cand)):
                return cand
        return "request_logs.json"

    def _log(status_str, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        fname = _pick_log_file()
        logs = _load(fname)
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
                "endpoint": endpoint,
                "status": status_str,
                "error_code": error_code,
                "latency_ms": latency_ms,
                "timestamp": _now_iso(),
            }
        )
        _save(fname, logs)

    def _is_str(x):
        return isinstance(x, str) and x != ""

    def _gen_id(prefix="f1_rc_"):
        # ULID-like sortable id; not cryptographically important
        # time component + random component
        ts = int(time.time() * 1000)
        rnd = secrets.token_hex(10)
        return f"{prefix}{ts:x}{rnd}"

    # -------- Validate envelope inputs --------
    yi, yerr = _parse_year(year)
    if yerr:
        _log("error", yerr["error"]["code"])
        return yerr

    if not isinstance(classifications, list):
        e = _err("VALIDATION_ERROR", "Parameter 'classifications' must be an array.")
        _log("error", e["error"]["code"])
        return e

    if set_event_status is not None and not isinstance(set_event_status, list):
        e = _err("VALIDATION_ERROR", "Parameter 'set_event_status' must be an array when provided.")
        _log("error", e["error"]["code"])
        return e

    # -------- Load datastore --------
    seasons = _load("seasons.json")
    events = _load("events.json")
    drivers = _load("drivers.json")
    constructors = _load("constructors.json")
    rcs = _load("race_classifications.json")

    if not isinstance(seasons, list):
        seasons = []
    if not isinstance(events, list):
        events = []
    if not isinstance(drivers, list):
        drivers = []
    if not isinstance(constructors, list):
        constructors = []
    if not isinstance(rcs, list):
        rcs = []

    season = None
    for s in seasons:
        if isinstance(s, dict) and s.get("year") == yi:
            season = s
            break
    if not season:
        e = _err("NOT_FOUND", f"Season for year {yi} was not found.")
        _log("error", e["error"]["code"])
        return e

    season_id = season.get("id")
    if not _is_str(season_id):
        e = _err("NOT_FOUND", f"Season for year {yi} has no valid id.")
        _log("error", e["error"]["code"])
        return e

    # Ingestion semantics: allow writes if season is refreshing OR pending/active/failed as ingestion can repair.
    if season.get("status") == "archived":
        e = _err("INVALID_TRANSITION", "Cannot upsert classifications for an archived season.")
        _log("error", e["error"]["code"])
        return e

    # Indexes for FK validation (only validate if provided, to accept minimal upserts).
    ev_by_id = {e.get("id"): e for e in events if isinstance(e, dict) and _is_str(e.get("id"))}
    drv_by_id = {d.get("id"): d for d in drivers if isinstance(d, dict) and _is_str(d.get("id"))}
    con_by_id = {c.get("id"): c for c in constructors if isinstance(c, dict) and _is_str(c.get("id"))}

    allowed_kinds = {"race_result", "driver_standing", "constructor_standing"}
    allowed_ds = {"provisional", "official", "amended"}

    # Pre-validate classification objects (do not require event_id for race_result if caller omitted it;
    # instead, enforce only what is possible: if they *do* provide it, it must exist and belong to season.
    # If they omit it, we accept (minimal upsert) but cannot guarantee event-scoped uniqueness; we treat it as a season-scoped row.
    validated = []
    for i, c in enumerate(classifications):
        if not isinstance(c, dict):
            e = _err("VALIDATION_ERROR", f"classifications[{i}] must be an object.")
            _log("error", e["error"]["code"])
            return e

        kind = c.get("kind")
        data_status = c.get("data_status")
        if kind not in allowed_kinds:
            e = _err("VALIDATION_ERROR", f"classifications[{i}].kind must be one of {sorted(allowed_kinds)}.")
            _log("error", e["error"]["code"])
            return e
        if data_status not in allowed_ds:
            e = _err("VALIDATION_ERROR", f"classifications[{i}].data_status must be one of {sorted(allowed_ds)}.")
            _log("error", e["error"]["code"])
            return e

        # Numeric validations
        def _check_int_field(name, minv=None):
            v = c.get(name, None)
            if v is None:
                return None
            if isinstance(v, bool) or not isinstance(v, int):
                return _err("VALIDATION_ERROR", f"classifications[{i}].{name} must be an integer.")
            if minv is not None and v < minv:
                return _err("VALIDATION_ERROR", f"classifications[{i}].{name} must be >= {minv}.")
            return None

        for fld, minv in (("position", 1), ("grid", 0), ("laps", 0), ("time_ms", 0), ("wins", 0), ("standing_round", 1)):
            verr = _check_int_field(fld, minv=minv)
            if verr:
                _log("error", verr["error"]["code"])
                return verr

        points = c.get("points", None)
        if points is not None:
            if isinstance(points, bool) or not isinstance(points, (int, float)):
                e = _err("VALIDATION_ERROR", f"classifications[{i}].points must be a number.")
                _log("error", e["error"]["code"])
                return e
            if float(points) < 0:
                e = _err("VALIDATION_ERROR", f"classifications[{i}].points must be >= 0.")
                _log("error", e["error"]["code"])
                return e

        event_id = c.get("event_id", None)
        driver_id = c.get("driver_id", None)
        constructor_id = c.get("constructor_id", None)
        standing_round = c.get("standing_round", None)

        # FK validation when provided
        if event_id is not None:
            if not _is_str(event_id):
                e = _err("VALIDATION_ERROR", f"classifications[{i}].event_id must be a non-empty string when provided.")
                _log("error", e["error"]["code"])
                return e
            ev = ev_by_id.get(event_id)
            if not ev:
                e = _err("NOT_FOUND", f"classifications[{i}].event_id '{event_id}' was not found.")
                _log("error", e["error"]["code"])
                return e
            if ev.get("season_id") != season_id:
                e = _err("CONFLICT", f"classifications[{i}].event_id '{event_id}' does not belong to season {yi}.")
                _log("error", e["error"]["code"])
                return e

        if driver_id is not None:
            if not _is_str(driver_id):
                e = _err("VALIDATION_ERROR", f"classifications[{i}].driver_id must be a non-empty string when provided.")
                _log("error", e["error"]["code"])
                return e
            d = drv_by_id.get(driver_id)
            if not d:
                e = _err("NOT_FOUND", f"classifications[{i}].driver_id '{driver_id}' was not found.")
                _log("error", e["error"]["code"])
                return e
            if d.get("season_id") != season_id:
                e = _err("CONFLICT", f"classifications[{i}].driver_id '{driver_id}' does not belong to season {yi}.")
                _log("error", e["error"]["code"])
                return e

        if constructor_id is not None:
            if not _is_str(constructor_id):
                e = _err("VALIDATION_ERROR", f"classifications[{i}].constructor_id must be a non-empty string when provided.")
                _log("error", e["error"]["code"])
                return e
            co = con_by_id.get(constructor_id)
            if not co:
                e = _err("NOT_FOUND", f"classifications[{i}].constructor_id '{constructor_id}' was not found.")
                _log("error", e["error"]["code"])
                return e
            if co.get("season_id") != season_id:
                e = _err("CONFLICT", f"classifications[{i}].constructor_id '{constructor_id}' does not belong to season {yi}.")
                _log("error", e["error"]["code"])
                return e

        # Enforce kind implications only for fields that are present in request schema:
        # Real defect: vendor schema does NOT require event_id/driver_id/constructor_id for race_result at parameter level,
        # so we must accept minimal rows (e.g., just kind + data_status) for ingestion placeholders.
        # However, if caller *provides* the required identifiers, they must be consistent.
        if kind == "race_result":
            # If any of these are provided, strongly encourage full tuple, but do not reject minimal.
            # The only hard rule we enforce: if event_id is provided, it must exist (handled above).
            pass
        elif kind == "driver_standing":
            # must be season-scoped snapshot (event_id must be null if provided in request)
            if event_id is not None:
                e = _err("VALIDATION_ERROR", f"classifications[{i}].event_id must be omitted for kind='driver_standing'.")
                _log("error", e["error"]["code"])
                return e
        elif kind == "constructor_standing":
            if event_id is not None:
                e = _err("VALIDATION_ERROR", f"classifications[{i}].event_id must be omitted for kind='constructor_standing'.")
                _log("error", e["error"]["code"])
                return e

        validated.append(
            {
                "i": i,
                "kind": kind,
                "data_status": data_status,
                "event_id": event_id,
                "driver_id": driver_id,
                "constructor_id": constructor_id,
                "standing_round": standing_round,
                "raw": c,
            }
        )

    # -------- Validate event status transitions + completion rule --------
    transitions = {"scheduled": {"completed", "cancelled"}, "completed": set(), "cancelled": set()}
    status_updates = []
    if set_event_status is not None:
        for j, u in enumerate(set_event_status):
            if not isinstance(u, dict):
                e = _err("VALIDATION_ERROR", f"set_event_status[{j}] must be an object.")
                _log("error", e["error"]["code"])
                return e
            event_id = u.get("event_id")
            st = u.get("status")
            if not _is_str(event_id):
                e = _err("VALIDATION_ERROR", f"set_event_status[{j}].event_id is required and must be a string.")
                _log("error", e["error"]["code"])
                return e
            if st not in ("scheduled", "completed", "cancelled"):
                e = _err("VALIDATION_ERROR", f"set_event_status[{j}].status must be one of ['scheduled','completed','cancelled'].")
                _log("error", e["error"]["code"])
                return e
            ev = ev_by_id.get(event_id)
            if not ev:
                e = _err("NOT_FOUND", f"set_event_status[{j}].event_id '{event_id}' was not found.")
                _log("error", e["error"]["code"])
                return e
            if ev.get("season_id") != season_id:
                e = _err("CONFLICT", f"set_event_status[{j}].event_id '{event_id}' does not belong to season {yi}.")
                _log("error", e["error"]["code"])
                return e
            cur = ev.get("status")
            if cur not in transitions:
                e = _err("VALIDATION_ERROR", f"Event '{event_id}' has invalid current status '{cur}'.")
                _log("error", e["error"]["code"])
                return e
            if st != cur and st not in transitions[cur]:
                e = _err("INVALID_TRANSITION", f"Cannot transition event '{event_id}' from '{cur}' to '{st}'.")
                _log("error", e["error"]["code"])
                return e

            # completion rule: must have at least one race_result for that event after this upsert
            if st == "completed" and cur != "completed":
                # count existing non-provisional race results for that event, plus any provided in this call (any data_status)
                existing = 0
                for row in rcs:
                    if isinstance(row, dict) and row.get("kind") == "race_result" and row.get("event_id") == event_id:
                        existing += 1
                        break
                incoming = 0
                for v in validated:
                    if v["kind"] == "race_result" and v["event_id"] == event_id:
                        incoming += 1
                        break
                if existing == 0 and incoming == 0:
                    e = _err(
                        "INVALID_TRANSITION",
                        f"Cannot mark event '{event_id}' completed: business rule requires at least one race_result row for that event.",
                        rule="event completion requires at least one race_result",
                    )
                    _log("error", e["error"]["code"])
                    return e

            status_updates.append((j, ev, st))

    # -------- Apply upserts atomically in memory --------
    now = _now_iso()

    # Helper: find match key per description: (event_id, kind, driver_id, constructor_id, standing_round) where applicable.
    def _match_key(cdict):
        return (
            cdict.get("event_id"),
            cdict.get("kind"),
            cdict.get("driver_id"),
            cdict.get("constructor_id"),
            cdict.get("standing_round"),
            cdict.get("season_id"),
        )

    # Build index for existing season rows only
    idx = {}
    for k, row in enumerate(rcs):
        if not isinstance(row, dict):
            continue
        if row.get("season_id") != season_id:
            continue
        idx[_match_key(row)] = k

    inserted = 0
    updated = 0

    # Allowed fields per schema/tool
    allowed_fields = {
        "event_id",
        "kind",
        "driver_id",
        "constructor_id",
        "position",
        "position_text",
        "points",
        "grid",
        "laps",
        "time_ms",
        "status_text",
        "wins",
        "standing_round",
        "data_status",
    }

    # data_status lifecycle transitions
    ds_trans = {"provisional": {"official", "amended"}, "official": {"amended"}, "amended": {"official"}}

    for v in validated:
        c = v["raw"]
        # build persisted row (season_id always enforced from year)
        new_row = {"season_id": season_id}
        for f in allowed_fields:
            if f in c:
                new_row[f] = c.get(f)

        # Ensure kind + data_status exist
        new_row["kind"] = v["kind"]
        new_row["data_status"] = v["data_status"]

        key = (v["event_id"], v["kind"], v["driver_id"], v["constructor_id"], v["standing_round"], season_id)
        existing_idx = idx.get(key)

        if existing_idx is None:
            # Insert
            new_row["id"] = _gen_id()
            new_row["created_at"] = now
            new_row["updated_at"] = now
            rcs.append(new_row)
            idx[key] = len(rcs) - 1
            inserted += 1
        else:
            # Update with lifecycle enforcement
            row = rcs[existing_idx]
            if not isinstance(row, dict):
                e = _err("CONFLICT", "Datastore corruption: classification row is not an object.")
                _log("error", e["error"]["code"])
                return e

            cur_ds = row.get("data_status")
            tgt_ds = new_row.get("data_status")
            if cur_ds in ds_trans and tgt_ds != cur_ds and tgt_ds not in ds_trans[cur_ds]:
                e = _err(
                    "INVALID_TRANSITION",
                    f"Cannot transition classification data_status from '{cur_ds}' to '{tgt_ds}'.",
                )
                _log("error", e["error"]["code"])
                return e

            # Apply fields (do not drop unspecified fields)
            for f in allowed_fields:
                if f in new_row:
                    row[f] = new_row[f]
            row["season_id"] = season_id  # enforce
            row["updated_at"] = now
            updated += 1

    # Apply event status updates
    events_updated = 0
    for _, ev, st in status_updates:
        if ev.get("status") != st:
            ev["status"] = st
            ev["updated_at"] = now
            events_updated += 1

    # Persist
    _save("race_classifications.json", rcs)
    if events_updated:
        _save("events.json", events)

    # Touch season updated_at (ingestion activity) without forcing lifecycle transition
    for s in seasons:
        if isinstance(s, dict) and s.get("id") == season_id:
            s["updated_at"] = now
            break
    _save("seasons.json", seasons)

    resp = {
        "season": {"id": season_id, "year": yi, "status": season.get("status"), "source": season.get("source")},
        "counts": {
            "classifications_inserted": inserted,
            "classifications_updated": updated,
            "events_updated": events_updated,
        },
        "timestamp": now,
    }
    _log("ok", None)
    return resp
